func signupExtraAttrs(f SignupExtraField) templ.Attributes {
	t := "text"
	switch f.Type {
	case "email":
		t = "email"
	case "tel":
		t = "tel"
	}
	a := templ.Attributes{"type": t, "id": f.Name}
	if f.Required {
		a["required"] = "required"
	}
	if f.Placeholder != "" {
		a["placeholder"] = f.Placeholder
	}
	return a
}

func donateStatusTone(status string) string {
	switch status {
	case "paid":
		return "success"
	case "refunded":
		return "warning"
	case "pending":
		return "info"
	default:
		return "neutral"
	}
}

func donateItoa(n int) string {
	if n == 0 {
		return "0"
	}
	buf := [20]byte{}
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	return string(buf[i:])
}

func pagesPluralize(n int, sing, plur string) string {
	if n == 1 {
		return "1 " + sing
	}
	b := make([]byte, 0, 10)
	if n == 0 {
		return "0 " + plur
	}
	tmp := n
	var digits []byte
	for tmp > 0 {
		digits = append(digits, byte('0'+tmp%10))
		tmp /= 10
	}
	for i := len(digits) - 1; i >= 0; i-- {
		b = append(b, digits[i])
	}
	return string(b) + " " + plur
}

